local module = {}

local _systems = {}
local _components = {}

module.GetSystems = function(systems: { ModuleScript | Folder })
	return _systems
end

module.GetComponents = function(components: { string })
	return _components
end

module.AddSystems = function(systems: { ModuleScript | Folder })
	for k, v in systems do
		table.insert(_systems, v)
	end
end

module.AddComponents = function(components: { string })
	for k, v in components do
		table.insert(_components, v)
	end
end

return module
